def set_uploaded_by(apps, schema_editor):
    """The first user with access to a document (lowest entry id) is taken as its uploader."""
    Document = apps.get_model('specs', 'Document')
    UserDocument = apps.get_model('specs', 'UserDocument')
    for document in Document.objects.filter(uploaded_by__isnull=True):
        first = UserDocument.objects.filter(document=document).order_by('id').first()
        if first is not None:
            document.uploaded_by_id = first.user_id
            document.save(update_fields=['uploaded_by'])


